class MyStack {
    private Queue<Integer> q1;
    private Queue<Integer> q2;
    private int top;  // cache top element for O(1) top()

    public MyStack() {
        q1 = new LinkedList<>();
        q2 = new LinkedList<>();
    }

    public void push(int x) {
        q1.offer(x);
        top = x;  // update top
    }

    public int pop() {
        while (q1.size() > 1) {
            top = q1.poll();  // update top to last moved
            q2.offer(top);
        }
        int popped = q1.poll();

        // Swap queues
        Queue<Integer> temp = q1;
        q1 = q2;
        q2 = temp;

        return popped;
    }

    public int top() {
        return top;
    }

    public boolean empty() {
        return q1.isEmpty();
    }
}


